cat > "$sys_lab/Pobierz.java" <<'EOF'
import java.net.ProxySelector;
import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;

public class Pobierz {
    public static void main(String[] args) throws Exception {
        HttpClient klient = HttpClient.newBuilder().proxy(ProxySelector.getDefault()).build();
        HttpResponse<String> odp = klient.send(HttpRequest.newBuilder(URI.create(args[0])).build(),
                HttpResponse.BodyHandlers.ofString());
        System.out.print("HTTP " + odp.statusCode() + ": " + odp.body());
    }
}
EOF
java "$sys_lab/Pobierz.java" "http://$ip_lab:18091/"
